from z3 import *

# 24 golfers, 4 weeks, 6 groups of 4
W = 4
P = 24
G = 6
S = 4

solver = Solver()

# x[w][p] is the group of golfer p in week w
x = [[Int(f"x_{w}_{p}") for p in range(P)] for w in range(W)]

# Domain constraints
for w in range(W):
    for p in range(P):
        solver.add(x[w][p] >= 0, x[w][p] < G)

# Group size constraints
for w in range(W):
    for g in range(G):
        solver.add(Sum([If(x[w][p] == g, 1, 0) for p in range(P)]) == S)

# No pair in same group more than once
for p1 in range(P):
    for p2 in range(p1 + 1, P):
        solver.add(Sum([If(x[w][p1] == x[w][p2], 1, 0) for w in range(W)]) <= 1)

# Symmetry breaking
# Week 0: golfer p is in group p // 4
for p in range(P):
    solver.add(x[0][p] == p // S)

# Golfer 0 is always in group 0
for w in range(W):
    solver.add(x[w][0] == 0)

# Week 1: golfers 0..3 are in groups 0..3
for p in range(S):
    solver.add(x[1][p] == p)

# Order groups by minimum golfer index
for w in range(1, W):
    for g in range(G - 1):
        # min_p_g is the minimum p such that x[w][p] == g
        # We can enforce this by saying: the first golfer in group g appears before the first golfer in group g+1
        # Actually, a simpler way:
        pass # Let's see if it solves quickly without this

if solver.check() == sat:
    m = solver.model()
    res = []
    for w in range(W):
        for p in range(P):
            res.append(m.evaluate(x[w][p]).as_long())
    print("SAT")
    print(res)
else:
    print("UNSAT")
